settings.custom_css:
selector {
    background: rgba(255, 255, 255, 0.12) !important;
    backdrop-filter: blur(1px) !important;
    -webkit-backdrop-filter: blur(18px) !important;
    border: 1px solid rgba(255, 255, 255, 0.25) !important;
   
    
}

selector .elementor-counter-number-suffix{
    font-size: 18px;
    display: inline-flex;
    align-items: center;
}

/* Container settings to establish relative context and stacking */
selector {
  position: relative;
  z-index: 1;
  overflow: visible !important;
}

/* Ensure inner content stays under the overlay */
selector > .elementor-container,
selector > .e-con-inner {
  z-index: 1;
}

/* Glow overlay pinned to the section */
selector::after {
  content: '';
  position: absolute;
  top: 50%;
  right: 0;
  transform: translateY(-50%);
  width: 110%; /* Adjust width as needed */
  height: 110%; /* Adjust height as needed */
  background-image: url('https://provision-infra.de/wp-content/uploads/2026/06/2.png');
  background-repeat: no-repeat;
  background-position: right center;
  background-size: contain;
  pointer-events: none; /* Clicks pass through to buttons/text underneath */
  z-index: 9999; /* Keeps glow on top of all content inside this section */
  opacity: 0.8;
}

/* Optional: Hide or resize on mobile */
@media (max-width: 767px) {
  selector::after {
    display: none;
  }
}

selector img{
    max-width: 110px;
}

@media (max-width: 767px) {
selector img{
    max-width: 80px;
}
}

html,
body {
  overflow-x: clip;
}



.shadeup {
  position: relative;
}

.shadeup::before {
  content: "";
  position: absolute;
  top: -10px; /* Centers the 20px height over the top boundary line */
  left: 0;
  width: 100%;
  height: 30px;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    #010c2d 50%,
    transparent 100%
  );
  pointer-events: none; /* Prevents interference with clicks */
  z-index: 10; /* Keeps the gradient above adjacent containers */
}
